function sdf(steps) {
    return (x, y) => {
        let d = Infinity;
        for (const s of steps) {
            const p = stepDist(s, x, y);
            d = s.cut ? Math.max(d, -p) : Math.min(d, p);
        }
        return d;
    };
}
